#!/usr/bin/env node
// Writes apps/web/src/light-palette.css: Tailwind's chromatic colour scales, muted for light mode.
//
// Every game paints with Tailwind's stock scales (amber, rose, sky…), which are tuned to be loud.
// In light mode the generated file re-points those scale variables at calmer versions of the same
// hues: chroma is scaled down (most for the pale tints that fill status boxes), and the mid shades
// are darkened a little so white text on a fill and coloured text on a card read better. Dark mode
// is untouched: the overrides only apply while `data-theme` is not `dark`.
//
//   node scripts/light-palette.mjs           # regenerate after a Tailwind upgrade or a tweak here
//
// scripts/light-palette.test.mjs fails when the committed file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const OUT = join(root, 'apps/web/src/light-palette.css');

/** The scales that get muted; stone, neutral and the greys are already calm. */
export const HUES = [
  'red',
  'orange',
  'amber',
  'yellow',
  'lime',
  'green',
  'emerald',
  'teal',
  'cyan',
  'sky',
  'blue',
  'indigo',
  'violet',
  'purple',
  'fuchsia',
  'pink',
  'rose',
];

/** Per shade: chroma factor and lightness shift (oklch L, 0–1). */
export const SHADES = {
  50: [0.5, 0],
  100: [0.45, 0],
  200: [0.5, 0],
  300: [0.55, -0.01],
  400: [0.6, -0.02],
  500: [0.66, -0.04],
  600: [0.72, -0.05],
  700: [0.8, -0.03],
  800: [0.86, -0.01],
  900: [0.92, 0],
  950: [0.96, 0],
};

export function tailwindTheme() {
  const require = createRequire(join(root, 'apps/web/package.json'));
  const pkg = require.resolve('tailwindcss/package.json');
  return readFileSync(join(dirname(pkg), 'theme.css'), 'utf8');
}

/** Parses `oklch(96.2% 0.059 95.617)` into [L (0–1), C, H]. */
export function parseOklch(value) {
  const m = /oklch\(\s*([\d.]+)(%?)\s+([\d.]+)\s+([\d.]+)\s*\)/.exec(value);
  if (!m) throw new Error(`not an oklch colour: ${value}`);
  const l = Number(m[1]) / (m[2] ? 100 : 1);
  return [l, Number(m[3]), Number(m[4])];
}

const round = (n, places) => Number(n.toFixed(places));
export const formatOklch = ([l, c, h]) =>
  `oklch(${round(l * 100, 1)}% ${round(c, 3)} ${round(h, 2)})`;

/** The muted light-mode value of every `--color-<hue>-<shade>` in Tailwind's theme. */
export function derive(themeCss) {
  const out = [];
  for (const hue of HUES) {
    for (const [shade, [cf, dl]] of Object.entries(SHADES)) {
      const m = new RegExp(`--color-${hue}-${shade}:\\s*([^;]+);`).exec(themeCss);
      if (!m) throw new Error(`Tailwind theme has no --color-${hue}-${shade}`);
      const [l, c, h] = parseOklch(m[1]);
      out.push([`--color-${hue}-${shade}`, formatOklch([Math.max(0, l + dl), c * cf, h])]);
    }
  }
  return out;
}

export function render(themeCss) {
  const lines = derive(themeCss).map(([name, value]) => `  ${name}: ${value};`);
  return [
    '/* Generated by scripts/light-palette.mjs: do not edit by hand. */',
    '/* Light mode only: calmer versions of the chromatic scales (dark mode keeps the stock ones). */',
    ":root:not([data-theme='dark']) {",
    ...lines,
    '}',
    '',
  ].join('\n');
}

// Colour maths for the contrast checks in the test.

/** oklch → linear sRGB channels (clamped to 0–1). */
export function oklchToLinearRgb([l, c, h]) {
  const a = c * Math.cos((h * Math.PI) / 180);
  const b = c * Math.sin((h * Math.PI) / 180);
  const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const clamp = (n) => Math.min(1, Math.max(0, n));
  return [
    clamp(4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_),
    clamp(-1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_),
    clamp(-0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_),
  ];
}

export function toHex(lch) {
  const enc = (v) => (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055);
  return (
    '#' +
    oklchToLinearRgb(lch)
      .map((v) =>
        Math.round(enc(v) * 255)
          .toString(16)
          .padStart(2, '0'),
      )
      .join('')
  );
}

/** WCAG contrast ratio of two oklch colours. */
export function contrast(a, b) {
  const lum = (lch) => {
    const [r, g, bl] = oklchToLinearRgb(lch);
    return 0.2126 * r + 0.7152 * g + 0.0722 * bl;
  };
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, render(tailwindTheme()));
  console.log(`wrote ${OUT}`);
}
